BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_leader_workspaces(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,enrollment_id UUID REFERENCES mission_bridge_enrollments(id),passage_reference TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_scripture_observations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,workspace_id UUID NOT NULL REFERENCES mission_bridge_leader_workspaces(id),observation TEXT NOT NULL,context_notes TEXT NOT NULL DEFAULT '',structure_notes TEXT NOT NULL DEFAULT '',central_message TEXT NOT NULL DEFAULT '',application_questions JSONB NOT NULL DEFAULT '[]'::jsonb,controversy_flags JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_leader_case_simulations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,case_type TEXT NOT NULL,response TEXT NOT NULL,reflection TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_leadership_reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,week INTEGER NOT NULL CHECK(week BETWEEN 1 AND 12),what_happened TEXT NOT NULL,what_was_heard TEXT NOT NULL,next_change TEXT NOT NULL,referral_categories JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,week));
CREATE TABLE IF NOT EXISTS mission_bridge_peer_supervisions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,peer_user_id TEXT NOT NULL,agenda TEXT NOT NULL,notes TEXT NOT NULL,consent_confirmed BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_sermon_self_reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,recording_object_key TEXT,transcript_consent BOOLEAN NOT NULL DEFAULT FALSE,self_review JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_apprentice_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,leader_user_id TEXT NOT NULL,apprentice_name TEXT NOT NULL,consent_confirmed BOOLEAN NOT NULL DEFAULT FALSE,development_goal TEXT NOT NULL,practice_steps JSONB NOT NULL DEFAULT '[]'::jsonb,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_offline_resources(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,program_id TEXT NOT NULL,title TEXT NOT NULL,resource_url TEXT NOT NULL,checksum TEXT NOT NULL,version TEXT NOT NULL,available_offline BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX IF NOT EXISTS idx_mb_leader_workspace_user ON mission_bridge_leader_workspaces(tenant_id,user_id,created_at DESC);CREATE INDEX IF NOT EXISTS idx_mb_leader_review_user ON mission_bridge_leadership_reviews(tenant_id,user_id,week);
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_leader_workspaces','mission_bridge_scripture_observations','mission_bridge_leader_case_simulations','mission_bridge_leadership_reviews','mission_bridge_peer_supervisions','mission_bridge_sermon_self_reviews','mission_bridge_apprentice_plans','mission_bridge_offline_resources'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
UPDATE mission_bridge_program_definitions SET title='基层带领者90天装备计划',active_version='2.0.0' WHERE id='local-leader-90';
INSERT INTO mission_bridge_program_versions(program_id,version,definition,safeguarding_profile) VALUES('local-leader-90','2.0.0','{"durationWeeks":12,"sessionMode":"hybrid","voluntary":true,"steps":12,"audience":["双职传道人","县城及城市边缘教会小组长","带领5至30人的平信徒同工"],"weeks":["带领者身份、呼召与边界","如何观察经文而不是先讲观点","经文背景、上下文和结构","从经文到中心信息","从真理到具体实践","如何提出开放式问题","如何倾听而不是立即教训","小组冲突与修复","识别精神健康和危机转介","培养副组长","权力、保密和反操控","设计下一轮门徒训练"],"aiRules":["不默认生成可照读讲章","优先提出经文观察问题","标记争议神学观点","不把个人意见包装为神告诉你"],"outcomes":["独立预备经文分享","识别至少三类转介问题","处理真实冲突","培养一位副组长","三个月后维持带领实践"]}'::jsonb,'{"riskTriggers":["self_harm","violence","abuse","medical_emergency","spiritual_abuse"],"professionalReferral":true,"noCoercion":true,"powerBoundaries":true}'::jsonb) ON CONFLICT DO NOTHING;
COMMIT;
